-- MP-0043: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin if not exists(select 1 from public.entities where slug='opposition' and type='bloc') then raise exception 'MP-0043: missing party parent'; end if; if exists(select 1 from public.entities where slug='muda' and (type <> 'party' or owner_id is not null or parent_id is distinct from (select id from public.entities where slug='opposition'))) then raise exception 'MP-0043: party identity conflict'; end if; end $$;

insert into public.entities (type,parent_id,slug,name,short_name,bloc,description,profile_checked_at,profile_sources) select 'party',parent.id,'muda','Malaysian United Democratic Alliance','MUDA','opposition','An opposition party outside PN. The October 2026 confidence-and-supply agreement does not establish government or PH membership.','2026-11-10','[{"label": "MUDA · current signatory and separate party identity", "url": "https://www.bernama.com/bm/am/news.php?id=2627381"}, {"label": "MUDA · opposition position, March 2026", "url": "https://malaysiagazette.com/2026/03/28/konflik-asia-barat-muda-sokong-cadangan-dr-sam-tubuh-j-kuasa-dwipartisan/"}, {"label": "SPR · current registered party emblems", "url": "https://www.spr.gov.my/parti-parti-yang-berdaftar/"}]'::jsonb from public.entities parent where parent.slug='opposition' and parent.type='bloc' on conflict (slug) do nothing;

do $$ begin
 if not exists(select 1 from public.entities where slug='amanah' and type='party') then raise exception 'MP-0043: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='mca' and type='party') then raise exception 'MP-0043: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='muda' and type='party') then raise exception 'MP-0043: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('syed-saddiq-syed-abdul-rahman','wee-ka-siong','aminolhuda-hassan') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0043: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('muar','ayer hitam','sri gading') and slug not in ('syed-saddiq-syed-abdul-rahman','wee-ka-siong','aminolhuda-hassan')) then raise exception 'MP-0043: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0043:%' and (m.source_type <> 'editorial' or e.slug not in ('syed-saddiq-syed-abdul-rahman','wee-ka-siong','aminolhuda-hassan') or m.import_key not like 'MP-0043:' || e.slug || ':%')) then raise exception 'MP-0043: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'syed-saddiq-syed-abdul-rahman','Syed Saddiq Syed Abdul Rahman','opposition','Member of the Dewan Rakyat; Founder and former president of MUDA','Muar','Johor','Syed Saddiq Syed Abdul Rahman represents Muar, Johor, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; Founder and former president of MUDA. Affiliated with MUDA.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4185','/portraits/syed-saddiq-syed-abdul-rahman.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P146.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4185"}, {"label": "MUDA · current October CSA signatory", "url": "https://www.bernama.com/bm/am/news.php?id=2627381"}, {"label": "MUDA · independent opposition position, March 2026", "url": "https://malaysiagazette.com/2026/03/28/konflik-asia-barat-muda-sokong-cadangan-dr-sam-tubuh-j-kuasa-dwipartisan/"}, {"label": "MUDA · March 2026 leadership election", "url": "https://www.bernama.com/bm/news.php?id=2534534"}]'::jsonb from public.entities parent where parent.slug='muda' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'wee-ka-siong','Wee Ka Siong','government','Member of the Dewan Rakyat; President of MCA','Ayer Hitam','Johor','Wee Ka Siong represents Ayer Hitam, Johor, in the Dewan Rakyat. Current role: Member of the Dewan Rakyat; President of MCA. Affiliated with MCA.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4187','/portraits/wee-ka-siong.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P148.png','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4187"}, {"label": "MCA representative · Ramadan constituency funding, 4 March 2026", "url": "https://www.thestar.com.my/news/nation/2026/03/04/dr-wee-provides-funding-for-community-activities-in-local-mosques-surau-in-ayer-hitam"}]'::jsonb from public.entities parent where parent.slug='mca' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'aminolhuda-hassan','Aminolhuda Hassan','government','Member of the Dewan Rakyat','Sri Gading','Johor','Aminolhuda Hassan represents Sri Gading, Johor, in the Dewan Rakyat. Affiliated with AMANAH.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4188','/portraits/aminolhuda-hassan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P149.jpg','Parliament of Malaysia','2026-11-10','[{"label": "Parliament · official current profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4188"}, {"label": "AMANAH · Johor leadership, 20 June 2026", "url": "https://www.astroawani.com/berita-politik/prn-johor-amanah-pertaruh-13-muka-baharu"}]'::jsonb from public.entities parent where parent.slug='amanah' and parent.type='party' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('syed-saddiq-syed-abdul-rahman','wee-ka-siong','aminolhuda-hassan') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0043: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0043:syed-saddiq-syed-abdul-rahman:muar-food-and-laptops','Fund 1,000 food baskets and 30 laptops for Muar','Social Welfare',null,null,null,'2026-06-23','https://www.siakapkeli.my/articles/syed-saddiq-salur-rm115000-hasil-kerja-sambilan-untuk-bantu-penduduk-muar',null,null,'Syed Saddiq pledged RM115,000 from filming work to buy the assistance items for constituents in need.','The article reports an intended contribution and shows some purchases. It does not verify that all baskets and laptops were delivered, so no completion percentage or achieved status is assigned.','2026-11-10','editorial',false from public.entities e where e.slug='syed-saddiq-syed-abdul-rahman' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0043:syed-saddiq-syed-abdul-rahman:budget-2027-csa','Support Supply Bill 2027 under the confidence-and-supply agreement','Governance',null,null,null,'2026-10-29','https://www.bernama.com/bm/am/news.php?id=2627381',null,null,'Signed the agreement committing support for the 2027 Supply Bill.','The agreement is documented. A subsequent budget vote or final passage was not established in this pass; signing is not counted as delivery of the bill or joining another party.','2026-11-10','editorial',false from public.entities e where e.slug='syed-saddiq-syed-abdul-rahman' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'MP-0043:wee-ka-siong:ramadan-mosque-surau-funding','Provide Ramadan activity funding to Ayer Hitam mosques and suraus','Community Development','achieved',null,null,null,null,'2026-03-04','https://www.thestar.com.my/news/nation/2026/03/04/dr-wee-provides-funding-for-community-activities-in-local-mosques-surau-in-ayer-hitam','Wee’s reported constituency funding supported imam and bilal activities across 29 mosques and 88 suraus.','A dated funding presentation report for this Ramadan round. It does not measure recipients’ later spending, religious outcomes or coverage of future annual rounds.','2026-11-10','editorial',false from public.entities e where e.slug='wee-ka-siong' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

